Map

maplibregl = (await import("https://esm.sh/maplibre-gl@4.7.1")).default

mapContainer = {
  const div = document.createElement("div");
  div.className = "talks-map";
  return div;
}

map = {
  const m = new maplibregl.Map({
    container: mapContainer,
    style: "https://tiles.openfreemap.org/styles/liberty",
    center: [4, 46],
    zoom: 3
  });
  m.addControl(new maplibregl.NavigationControl(), "top-right");

  m.on("load", () =&gt; {
    if (!talks_map_data.length) return;
    const bounds = new maplibregl.LngLatBounds();
    talks_map_data.forEach((t) =&gt; {
      const meta = [t.date, t.location].filter(Boolean).join(" · ");
      const popupHtml = `&lt;strong&gt;${t.event}&lt;/strong&gt;` +
        (meta ? `&lt;br&gt;${meta}` : "") +
        `&lt;br&gt;&lt;a href="#${t.alias}" onclick="window.__talksSelect && window.__talksSelect('${t.alias}')"&gt;View talk ↓&lt;/a&gt;`;
      new maplibregl.Marker({ color: "#eb6864" })
        .setLngLat([t.lng, t.lat])
        .setPopup(new maplibregl.Popup({ offset: 25 }).setHTML(popupHtml))
        .addTo(m);
      bounds.extend([t.lng, t.lat]);
    });
    m.fitBounds(bounds, { padding: 60, maxZoom: 8 });
  });

  return m;
}
